const items = $input.all();
const base = $('Parse Enrichment').first().json;

const industryData = items.find(i => i.json.choices?.[0]?.message?.content);
const competitorData = items.find(i => i.json.choices?.[0]?.message?.content && i !== industryData);
const toolData = items.find(i => i.json.message?.content?.[0]?.text);

const industryFallback = items.find(i => i.json.industryResearch);
const competitorFallback = items.find(i => i.json.competitorResearch);
const toolFallback = items.find(i => i.json.toolAudit);
const skipResearch = items.find(i => i.json.researchSkipped);

if (skipResearch) {
  return [{
    json: {
      ...base,
      industryResearch: 'Research skipped - budget constraints',
      competitorResearch: 'Research skipped - budget constraints',
      toolAudit: 'Research skipped - budget constraints'
    }
  }];
}

return [{
  json: {
    ...base,
    industryResearch: industryData?.json?.choices?.[0]?.message?.content || industryFallback?.json?.industryResearch || 'No industry research available',
    competitorResearch: competitorData?.json?.choices?.[0]?.message?.content || competitorFallback?.json?.competitorResearch || 'No competitor research available',
    toolAudit: toolData?.json?.message?.content?.[0]?.text || toolFallback?.json?.toolAudit || 'No tool audit available'
  }
}];

const input = $input.first().json;
const suggestionReport = input.output || input?.message?.content?.[0]?.text || '';

const chunkText = (text, maxLength = 1800) => {
  const chunks = [];
  const paragraphs = text.split('\n\n');
  let currentChunk = '';

  for (const para of paragraphs) {
    if ((currentChunk + para).length > maxLength && currentChunk) {
      chunks.push(currentChunk.trim());
      currentChunk = para;
    } else {
      currentChunk += (currentChunk ? '\n\n' : '') + para;
    }
  }
  if (currentChunk) chunks.push(currentChunk.trim());
  return chunks;
};

const original = $('Assemble Context').first().json;

return [{
  json: {
    ...original,
    suggestionReport,
    reportChunks: chunkText(suggestionReport)
  }
}];

const input = $input.first().json;
const proposal = input.output || input?.message?.content?.[0]?.text || '';
const suggestionReport = $('Opus Synthesis').first().json.output || '';
const base = $('Assemble Context').first().json;

return [{
  json: {
    ...base,
    suggestionReport: suggestionReport,
    clientProposal: proposal,
    reportChunks: suggestionReport.match(/.{1,1900}(\s|$)/gs) || [suggestionReport],
