const input = $('Parse Proposal').first().json;
const suggestionReport = input.suggestionReport || '';
const clientProposal = input.clientProposal || '';

// Function to chunk text into ~1900 character segments at paragraph boundaries
const chunkText = (text, maxLength = 1900) => {
  const chunks = [];
  const paragraphs = text.split('\n\n');
  let currentChunk = '';

  for (const para of paragraphs) {
    if ((currentChunk + para).length > maxLength && currentChunk) {
      chunks.push(currentChunk.trim());
      currentChunk = para;
    } else {
      currentChunk += (currentChunk ? '\n\n' : '') + para;
    }
  }
  if (currentChunk) chunks.push(currentChunk.trim());
  return chunks;
};

// Create chunks
const reportChunks = chunkText(suggestionReport);
const proposalChunks = chunkText(clientProposal);

// Build Notion paragraph block arrays
const reportBlocks = reportChunks.map(chunk => ({
  type: 'paragraph',
  paragraph: {
    rich_text: [{
      type: 'text',
      text: { content: chunk }
    }]
  }
}));

const proposalBlocks = proposalChunks.map(chunk => ({
  type: 'paragraph',
  paragraph: {
    rich_text: [{
      type: 'text',
      text: { content: chunk }
    }]
  }
}));

return [{
  json: {
    ...input,
    reportChunks,
    proposalChunks,
    reportBlocks,
    proposalBlocks
  }
}];

